// MobileNavigationMegaMenuComponent.js
import React, { useState, memo } from "react";

// Generic recursive list that enforces "one open at a time" per level.
const MobileMenuList = memo(function MobileMenuList({ items }) {
  const [openIndex, setOpenIndex] = useState(null);

  const handleToggle = (i, hasChildren, e) => {
    if (!hasChildren) return; // normal links just work
    e.preventDefault(); // stop navigation for accordion parents
    setOpenIndex((prev) => (prev === i ? null : i)); // close siblings
  };

  return (
    <ul className="mobile-submenu">
      {items.map((item, i) => {
        const hasChildren = Array.isArray(item.children) && item.children.length > 0;
        const isOpen = openIndex === i;

        return (
          <li
            key={i}
            className={`${
              hasChildren ? "mobile-has-submenu" : ""
            } ${isOpen ? "mobile-open" : ""}`}
          >
            <a
              href={item.href || "#"}
              target={item.external ? "_blank" : undefined}
              rel={item.external ? "noopener noreferrer" : undefined}
              onClick={(e) => handleToggle(i, hasChildren, e)}
            >
              {item.label}
            </a>

            {hasChildren && (
              <div
                className="mobile-submenu-wrapper"
                style={{ display: isOpen ? "block" : "none" }}
              >
                <MobileMenuList items={item.children} />
              </div>
            )}
          </li>
        );
      })}
    </ul>
  );
});

