export default function MobileNavigationMegaMenuComponent() {
  const [menuOpen, setMenuOpen] = useState(false);

  return (
    <div className="mobile-navigations-bar header">
      {/* Top bar */}
      <nav className="mobile-navbar">
        <div className="mobile-logo">
          <a href="https://www.accorian.com/" target="_blank" rel="noopener noreferrer">
            <img
              src="https://www.accorian.com/wp-content/uploads/2024/10/Accorian-Logo.svg"
              alt="Accorian Logo"
            />
          </a>
        </div>

        <button
          aria-label="Toggle menu"
          className="mobile-hamburger"
          onClick={() => setMenuOpen((s) => !s)}
        >
          {/* bootstrap icons class swap */}
          <i className={`bi ${menuOpen ? "bi-x" : "bi-list"}`} />
        </button>
      </nav>

      {/* Menu */}
      <div className="mobile-menu-container" style={{ display: menuOpen ? "block" : "none" }}>
        <ul className="mobile-menu">
          {/* Render the first level with our recursive list for consistency */}
          <MobileMenuList items={MENU} />
        </ul>
      </div>
    </div>
  );
}
